.uv-mac {
  --c1: #111827;
  --c2: #f97316;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uv-mac {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  position: relative;
  border-radius: 1.3em;
  background: color-mix(in srgb,var(--fg) 2%,var(--bg));
  box-shadow: 0 0 0 1px color-mix(in srgb,var(--fg) 9%,transparent),0 1.4em 2.6em -1.8em rgba(0,0,0,.35);
  width: 18em;
  padding: 1em;
}

.uv-mac header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: .9em;
}

.uv-mac header b {
  font-size: 1.05em;
  letter-spacing: -.01em;
}

.uv-mac .ct {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  position: relative;
  display: grid;
  place-items: center;
  width: 2.6em;
  height: 2.6em;
  border-radius: 50%;
  background: color-mix(in srgb,var(--fg) 6%,transparent);
}

.uv-mac .ct svg {
  width: 1.25em;
  height: 1.25em;
}

.uv-mac .ct:focus-visible,.uv-mac .ad:focus-visible {
  outline: 2px solid var(--c1);
  outline-offset: 3px;
}

.uv-mac .n {
  position: absolute;
  top: -.2em;
  right: -.2em;
  min-width: 1.4em;
  height: 1.4em;
  padding: 0 .3em;
  border-radius: 1em;
  display: grid;
  place-items: center;
  font-size: .7em;
  font-weight: 800;
  color: #fff;
  background: var(--c2);
  box-sizing: border-box;
  transform: scale(0);
  transition: transform calc(0.35s / var(--k)) cubic-bezier(.34,1.56,.64,1);
}

.uv-mac.has .n {
  transform: scale(1);
}

.uv-mac .sr {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}

.uv-mac .ct.bp {
  animation: uv-mac-b calc(0.45s / var(--k)) cubic-bezier(.34,1.56,.64,1);
}

@keyframes uv-mac-b {
  30% {
    transform: scale(1.25) rotate(-8deg);
  }
  60% {
    transform: scale(.92) rotate(4deg);
  }
}

.uv-mac .pr {
  display: grid;
  grid-template-columns: 5.2em 1fr;
  gap: .9em;
  align-items: center;
}

.uv-mac .im {
  display: grid;
  place-items: center;
  width: 5.2em;
  height: 5.2em;
  border-radius: 1em;
  background: radial-gradient(120% 90% at 20% 10%,color-mix(in srgb,var(--c2) 55%,#fff),var(--c2));
}

.uv-mac .im svg {
  width: 72%;
}

.uv-mac .fly {
  position: absolute;
  left: 0;
  top: 0;
  z-index: 5;
  pointer-events: none;
  box-shadow: 0 .8em 1.6em -.6em rgba(0,0,0,.4);
}

.uv-mac .tx b {
  display: block;
  font-size: .95em;
}

.uv-mac .tx span {
  display: block;
  margin: .15em 0 .35em;
  font-size: .75em;
  color: color-mix(in srgb,var(--fg) 55%,transparent);
}

.uv-mac .tx em {
  font-style: normal;
  font-weight: 800;
}

.uv-mac .ad {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  position: relative;
  display: grid;
  width: 100%;
  margin-top: 1em;
  padding: .85em;
  border-radius: .9em;
  font-weight: 700;
  color: var(--bg);
  background: var(--c1);
  overflow: hidden;
  transition: background calc(0.3s / var(--k)) cubic-bezier(.25,.1,.25,1),transform .15s cubic-bezier(.25,.1,.25,1);
}

.uv-mac .ad:active {
  transform: scale(.97);
}

.uv-mac .ad>span {
  grid-area: 1/1;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: .4em;
  transition: transform calc(0.4s / var(--k)) cubic-bezier(.22,1,.36,1),opacity calc(0.3s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uv-mac .ad svg {
  width: 1.1em;
  height: 1.1em;
}

.uv-mac .ad .b {
  transform: translateY(120%);
  opacity: 0;
}

.uv-mac .ad.ok {
  background: #16a34a;
}

.uv-mac .ad.ok .a {
  transform: translateY(-120%);
  opacity: 0;
}

.uv-mac .ad.ok .b {
  transform: none;
  opacity: 1;
}

@media (prefers-color-scheme:dark) {
  .uv-mac .ad {
    color: #fff;
    background: color-mix(in srgb,var(--c1) 40%,#3f3f46);
  }
}

@media (prefers-reduced-motion:reduce) {
  .uv-mac,.uv-mac *,.uv-mac *::before,.uv-mac *::after {
    animation-duration: .01ms!important;
    animation-iteration-count: 1!important;
    transition-duration: .01ms!important;
  }
}

