document.querySelectorAll(".uv-mac").forEach(el => {
  const k=parseFloat(getComputedStyle(el).getPropertyValue("--k"))||1,rm=matchMedia("(prefers-reduced-motion:reduce)").matches;const ad=el.querySelector(".ad"),ct=el.querySelector(".ct"),n=el.querySelector(".n"),im=el.querySelector(".im");let c=0,tm=0;
const bump=()=>{c++;n.textContent=String(c);ct.classList.remove("bp");void ct.offsetWidth;ct.classList.add("bp");el.classList.add("has")};
ad.addEventListener("click",()=>{ad.classList.add("ok");clearTimeout(tm);tm=setTimeout(()=>ad.classList.remove("ok"),1400/k);if(rm){bump();return}
const r=el.getBoundingClientRect(),a=im.getBoundingClientRect(),b=ct.getBoundingClientRect(),f=im.cloneNode(true);f.classList.add("fly");f.style.width=a.width+"px";f.style.height=a.height+"px";el.appendChild(f);
const sx=a.left-r.left,sy=a.top-r.top,ex=b.left-r.left+b.width/2-a.width/2,ey=b.top-r.top+b.height/2-a.height/2,fr=[];
for(let i=0;i<=16;i++){const t=i/16;fr.push({transform:"translate("+(sx+(ex-sx)*t)+"px,"+(sy+(ey-sy)*t-110*4*t*(1-t))+"px) scale("+(1-.84*t)+") rotate("+t*30+"deg)"})}
f.animate(fr,{duration:800/k,easing:"cubic-bezier(.45,0,.55,1)"}).onfinish=()=>{f.remove();bump()}});return()=>clearTimeout(tm)
});

