.uv-mpr {
  --c1: #6366f1;
  --c2: #ffffff;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uv-mpr {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  position: relative;
  border-radius: 1.3em;
  background: color-mix(in srgb,var(--fg) 2%,var(--bg));
  box-shadow: 0 0 0 1px color-mix(in srgb,var(--fg) 9%,transparent),0 1.4em 2.6em -1.8em rgba(0,0,0,.35);
  width: 19em;
  height: 17em;
  overflow: hidden;
  --y: 0px;
  --r: 0;
}

.uv-mpr .ind {
  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  height: 56px;
  display: grid;
  place-items: center;
  opacity: var(--r);
}

.uv-mpr .ind svg {
  width: 1.6em;
  height: 1.6em;
  fill: none;
  stroke: var(--c1);
  stroke-width: 2.6;
  stroke-linecap: round;
  stroke-dasharray: calc(var(--r) * 38) 60;
  transform: rotate(calc(var(--r) * 300deg - 90deg));
}

.uv-mpr.ld .ind svg {
  stroke-dasharray: 30 60;
  animation: uv-mpr calc(0.8s / var(--k)) linear infinite;
}

