css:
.uv-msw {
  --c1: #16a34a;
  --c2: #e11d48;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uv-msw {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  position: relative;
  border-radius: 1.3em;
  background: color-mix(in srgb,var(--fg) 2%,var(--bg));
  box-shadow: 0 0 0 1px color-mix(in srgb,var(--fg) 9%,transparent),0 1.4em 2.6em -1.8em rgba(0,0,0,.35);
  width: 20em;
  padding: .8em 0 .4em;
  overflow: hidden;
}

.uv-msw .hd {
  display: grid;
  gap: .1em;
  margin: 0 1em .5em;
}

.uv-msw .hd small {
  font-size: .7em;
  color: color-mix(in srgb,var(--fg) 55%,transparent);
}

.uv-msw .ls {
  margin: 0;
  padding: 0;
  list-style: none;
}

.uv-msw .rw {
  position: relative;
  height: 4em;
  overflow: hidden;
  transition: height calc(0.35s / var(--k)) cubic-bezier(.25,.1,.25,1),opacity calc(0.3s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uv-msw .ac {
  position: absolute;
  top: 0;
  right: 0;
  bottom: 0;
  display: flex;
}

.uv-msw .ac button {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  flex: none;
  width: 4.6em;
  display: grid;
  place-content: center;
  justify-items: center;
  gap: .2em;
  font-size: .8em;
  font-weight: 700;
  color: #fff;
  transition: width calc(0.25s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uv-msw .ac svg {
  width: 1.4em;
  height: 1.4em;
}

.uv-msw .rw .ac .ar {
  background: var(--c1);
}

.uv-msw .rw .ac .dl {
  background: var(--c2);
}

.uv-msw .ac button:focus-visible {
  outline: 2px solid #fff;
  outline-offset: -4px;
}

.uv-msw .fg {
  position: relative;
  height: 100%;
  display: grid;
  grid-template-columns: 2.4em 1fr auto;
  gap: .7em;
  align-items: center;
  padding: 0 1em;
  background: color-mix(in srgb,var(--fg) 2%,var(--bg));
  box-shadow: 0 1px 0 color-mix(in srgb,var(--fg) 9%,transparent);
  transition: transform calc(0.4s / var(--k)) cubic-bezier(.22,1,.36,1);
  touch-action: pan-y;
  cursor: grab;
  user-select: none;
}

.uv-msw .rw.drag .fg {
  transition: none;
  cursor: grabbing;
}

.uv-msw .rw.open .fg,.uv-msw .rw:focus-within .fg {
  transform: translateX(-7.4em);
}

.uv-msw .rw.far .ac {
  left: 0;
}

.uv-msw .rw.far .ac .ar {
  width: 0;
  overflow: hidden;
}

.uv-msw .rw.far .ac .dl {
  flex: 1;
  place-content: center end;
  padding-right: 1.4em;
}

.uv-msw .rw.gone {
  height: 0;
  opacity: 0;
}

.uv-msw .rw.gone .fg {
  transform: translateX(-110%);
}

.uv-msw .av {
  display: grid;
  place-items: center;
  width: 2.4em;
  height: 2.4em;
  border-radius: 50%;
  font-weight: 800;
  color: #fff;
  background: var(--c);
}

.uv-msw .fg b {
  display: block;
  font-size: .9em;
}

.uv-msw .fg span:not(.av) {
  display: block;
  font-size: .78em;
  color: color-mix(in srgb,var(--fg) 55%,transparent);
}

.uv-msw time {
  font-size: .7em;
  color: color-mix(in srgb,var(--fg) 55%,transparent);
}

.uv-msw .em {
  display: none;
  place-items: center;
  gap: .6em;
  padding: 2.4em 1em 2em;
  text-align: center;
}

.uv-msw.empty .em {
  display: grid;
}

.uv-msw .rs {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  padding: .45em .9em;
  border-radius: 2em;
  font-size: .8em;
  font-weight: 700;
  background: color-mix(in srgb,var(--fg) 6%,transparent);
}

.uv-msw .rs:focus-visible {
  outline: 2px solid var(--c1);
  outline-offset: 3px;
}

.uv-msw .sr {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}

@media (prefers-reduced-motion:reduce) {
  .uv-msw,.uv-msw *,.uv-msw *::before,.uv-msw *::after {
    animation-duration: .01ms!important;
    animation-iteration-count: 1!important;
    transition-duration: .01ms!important;
  }
}

