  border-top: 1px solid color-mix(in srgb,var(--fg) 9%,transparent);
}

.uv-mhr li {
  border-bottom: 1px solid color-mix(in srgb,var(--fg) 9%,transparent);
}

.uv-mhr a {
  display: grid;
  grid-template-columns: 1fr auto 3.2em;
  align-items: baseline;
  gap: 1em;
  padding: .55em .2em;
  color: var(--c1);
  text-decoration: none;
  transition: opacity calc(0.3s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uv-mhr a b {
  font-size: 2em;
  font-weight: 800;
  letter-spacing: -.04em;
  transition: transform calc(0.4s / var(--k)) cubic-bezier(.22,1,.36,1),color calc(0.3s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uv-mhr a span,.uv-mhr a time {
  font-size: .78em;
  color: color-mix(in srgb,var(--fg) 55%,transparent);
}

.uv-mhr a time {
  text-align: right;
  font-variant-numeric: tabular-nums;
}

.uv-mhr ul:has(a.cur) a:not(.cur) {
  opacity: .3;
}

.uv-mhr a.cur b {
  transform: translateX(.25em);
  color: var(--c2);
}

.uv-mhr a:focus-visible {
  outline: 2px solid var(--c1);
