  --b: #7c3aed;
}

.uv-mhr .pv i {
  display: grid;
  place-items: center;
  width: 9em;
  height: 6.4em;
  border-radius: .9em;
  background: radial-gradient(70% 90% at 80% 10%,rgba(255,255,255,.35),transparent 60%),linear-gradient(140deg,var(--a),var(--b));
  box-shadow: 0 1.4em 2.4em -1em color-mix(in srgb,var(--b) 70%,transparent);
  transform: scale(.3);
  opacity: 0;
  transition: transform calc(0.45s / var(--k)) cubic-bezier(.22,1,.36,1),opacity calc(0.25s / var(--k)) cubic-bezier(.25,.1,.25,1),background calc(0.3s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uv-mhr .pv i::after {
  content: attr(data-l);
  font-size: 3.2em;
  font-weight: 900;
  font-style: normal;
  color: rgba(255,255,255,.9);
  letter-spacing: -.05em;
}

