  box-shadow: 0 0 0 1px color-mix(in srgb,var(--fg) 9%,transparent),0 .8em 1.6em -1em rgba(0,0,0,.35);
  touch-action: manipulation;
  user-select: none;
  transition: color calc(0.3s / var(--k)) cubic-bezier(.25,.1,.25,1),box-shadow calc(0.3s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uv-mcl .b:hover {
  box-shadow: 0 0 0 1.5px var(--c1),0 .8em 1.6em -1em rgba(0,0,0,.35);
}

.uv-mcl .b:focus-visible {
  outline: 2px solid var(--c1);
  outline-offset: 3px;
}

.uv-mcl.did .b {
  color: var(--c1);
}

.uv-mcl .ic {
  display: grid;
}

.uv-mcl .ic svg {
  width: 2em;
  height: 2em;
}

.uv-mcl .sp {
  opacity: 0;
}

.uv-mcl.did .sp {
  opacity: 1;
}

.uv-mcl .b.go .ic {
  animation: uv-mcl-p calc(0.35s / var(--k)) cubic-bezier(.34,1.56,.64,1);
}

@keyframes uv-mcl-p {
  40% {
    transform: scale(.82) rotate(-8deg);
  }
}

.uv-mcl .pt {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.uv-mcl .pt i {
  position: absolute;
  left: 50%;
  top: 50%;
  width: .32em;
  height: .32em;
  margin: -.16em;
  border-radius: 50%;
  background: var(--c2);
  opacity: 0;
