  }
  100% {
    opacity: 0;
    transform: rotate(var(--a)) translateY(-3.3em);
  }
}

.uv-mcl .bub {
  position: absolute;
  left: 50%;
  top: -.6em;
  display: grid;
  place-items: center;
  min-width: 2.4em;
  height: 2.4em;
  padding: 0 .3em;
  box-sizing: border-box;
  border-radius: 50%;
  font-size: .85em;
  font-weight: 800;
  color: #fff;
  background: var(--c1);
  translate: -50% 0;
  opacity: 0;
  pointer-events: none;
}

.uv-mcl .b.go .bub {
  animation: uv-mcl-b calc(0.9s / var(--k)) cubic-bezier(.22,1,.36,1);
}

@keyframes uv-mcl-b {
  0% {
    opacity: 0;
