.uvq15-plg {
  --c1: #16a34a;
  --c2: #f59e0b;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uvq15-plg {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  position: relative;
  border-radius: 1.3em;
  background: color-mix(in srgb,var(--fg) 3%,var(--bg));
  box-shadow: 0 0 0 1px color-mix(in srgb,var(--fg) 10%,transparent),0 1.4em 2.6em -1.8em rgba(0,0,0,.35);
  display: grid;
  gap: .8em;
  width: 18em;
  padding: 1em;
}

.uvq15-plg .sc {
  display: block;
  width: 100%;
  height: auto;
  overflow: visible;
  border-radius: .8em;
  background: color-mix(in srgb,var(--fg) 6%,transparent);
  touch-action: none;
}

.uvq15-plg .cb {
  fill: none;
  stroke: color-mix(in srgb,var(--fg) 70%,transparent);
  stroke-width: 5;
  stroke-linecap: round;
}

.uvq15-plg .pg {
  cursor: grab;
}

.uvq15-plg.drag .pg {
  cursor: grabbing;
}

.uvq15-plg .bd {
  fill: #e5e7eb;
  stroke: #9ca3af;
  stroke-width: 1.5;
}

.uvq15-plg .gr {
  fill: #6b7280;
}

.uvq15-plg .hl {
  fill: #fff;
  opacity: .7;
}

.uvq15-plg .pr {
  fill: #d4a017;
  stroke: #a16207;
  stroke-width: 1;
}

.uvq15-plg .pl {
  fill: #f1f5f9;
  stroke: #cbd5e1;
  stroke-width: 1.5;
}

.uvq15-plg .ho {
  fill: #1f2937;
}

.uvq15-plg .led {
  fill: #cbd5e1;
  transition: fill calc(0.3s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq15-plg.on .led {
  fill: var(--c1);
  filter: drop-shadow(0 0 3px var(--c1));
}

.uvq15-plg .spk line {
  stroke: var(--c2);
  stroke-width: 2.5;
  stroke-linecap: round;
  opacity: 0;
}

.uvq15-plg .spk.go line {
  animation: uvq15-plg-s calc(0.45s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

@keyframes uvq15-plg-s {
  0% {
    opacity: 1;
    stroke-dasharray: 0 20;
  }
  40% {
    opacity: 1;
    stroke-dasharray: 10 20;
  }
  100% {
    opacity: 0;
    stroke-dasharray: 10 20;
    stroke-dashoffset: -10;
  }
}

.uvq15-plg .ft {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: .8em;
}

.uvq15-plg .st {
  display: flex;
  align-items: center;
  gap: .45em;
  margin: 0;
  font-size: .85em;
}

.uvq15-plg .st i {
  width: .6em;
  height: .6em;
  border-radius: 50%;
  background: #ef4444;
  box-shadow: 0 0 0 .2em color-mix(in srgb,#ef4444 20%,transparent);
  transition: background calc(0.3s / var(--k)) cubic-bezier(.25,.1,.25,1),box-shadow calc(0.3s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq15-plg.try .st i {
  background: var(--c2);
  animation: uvq15-plg-p calc(0.8s / var(--k)) ease-in-out infinite;
}

@keyframes uvq15-plg-p {
  50% {
    opacity: .3;
  }
}

.uvq15-plg.on .st i {
  background: var(--c1);
  box-shadow: 0 0 0 .2em color-mix(in srgb,var(--c1) 22%,transparent);
}

.uvq15-plg .bt {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  padding: .6em 1.1em;
  border-radius: .7em;
  font-size: .9em;
  font-weight: 700;
  color: #fff;
  background: var(--c1);
  transition: background calc(0.2s / var(--k)) cubic-bezier(.25,.1,.25,1),color calc(0.2s / var(--k)) cubic-bezier(.25,.1,.25,1),transform .15s cubic-bezier(.25,.1,.25,1);
}

.uvq15-plg .bt:hover {
  filter: brightness(1.08);
}

.uvq15-plg .bt:active {
  transform: scale(.96);
}

.uvq15-plg .bt:focus-visible {
  outline: 2px solid var(--c1);
  outline-offset: 3px;
}

.uvq15-plg.on .bt {
  color: var(--fg);
  background: color-mix(in srgb,var(--fg) 6%,transparent);
}

@media (prefers-reduced-motion:reduce) {
  .uvq15-plg,.uvq15-plg *,.uvq15-plg *::before,.uvq15-plg *::after {
    animation-duration: .01ms!important;
    animation-iteration-count: 1!important;
    transition-duration: .01ms!important;
  }
}

