pg.addEventListener("pointerdown",e=>{drag=true;cancelAnimationFrame(raf);raf=0;v=0;gx=sx(e)-x;sc.setPointerCapture(e.pointerId);el.classList.add("drag")});
sc.addEventListener("pointermove",e=>{if(!drag)return;x=Math.max(30,Math.min(X1,sx(e)-gx));draw();if(x>=X1-.5)plugged();else loose()});
const up=()=>{if(!drag)return;drag=false;el.classList.remove("drag");if(x>=X1-30){el.classList.add("try");st.textContent="Conectando…"}go(x>=X1-30?X1:X0)};sc.addEventListener("pointerup",up);sc.addEventListener("pointercancel",up);
bt.addEventListener("click",()=>{if(on){v=-6;go(X0);return}el.classList.add("try");st.textContent="Conectando…";go(X1)});draw();return()=>cancelAnimationFrame(raf)
});

