  gap: .6em;
  padding: .8em 1em;
  box-shadow: 0 1px 0 color-mix(in srgb,var(--fg) 10%,transparent);
}

.uvq15-cht .av {
  display: grid;
  place-items: center;
  width: 2.2em;
  height: 2.2em;
  border-radius: 50%;
