  overflow-y: auto;
  list-style: none;
  box-sizing: border-box;
  scrollbar-width: none;
}

.uvq15-cht li {
  max-width: 78%;
  display: grid;
}

.uvq15-cht .tx {
  display: block;
  padding: .5em .8em;
  border-radius: 1.1em;
  font-size: .85em;
  line-height: 1.35;
  overflow-wrap: anywhere;
}

.uvq15-cht li:first-child {
  margin-top: auto;
}

.uvq15-cht .in .tx {
  border-bottom-left-radius: .3em;
  background: color-mix(in srgb,var(--fg) 6%,transparent);
}

.uvq15-cht .out {
  align-self: flex-end;
  justify-items: end;
}

.uvq15-cht .out .tx {
  border-bottom-right-radius: .3em;
  color: #fff;
  background: var(--c1);
}

.uvq15-cht .rc {
  display: flex;
  align-items: center;
  gap: .2em;
  margin-top: .2em;
  font-size: .65em;
  color: color-mix(in srgb,var(--fg) 55%,transparent);
}

.uvq15-cht .rc svg {
  width: 1.4em;
  height: 1.4em;
  fill: none;
  stroke: currentColor;
  stroke-width: 2.2;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.uvq15-cht .rc .t2 {
  opacity: 0;
  transition: opacity calc(0.25s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq15-cht .rc.dl .t2 {
  opacity: 1;
}

.uvq15-cht .rc.rd {
  color: var(--c2);
}

