.uvq15-nps {
  --c1: #ef4444;
  --c2: #18181b;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --bnc: 60;
  /* rebote */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uvq15-nps {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  display: grid;
  justify-items: center;
  gap: .6em;
  width: 16em;
  --z: #f59e0b;
}

.uvq15-nps .q {
  margin: 0;
  font-weight: 700;
  text-align: center;
}

.uvq15-nps .dl {
  position: relative;
  width: 14em;
  height: 14em;
  border-radius: 50%;
  cursor: grab;
  touch-action: none;
  outline: 0;
  user-select: none;
}

.uvq15-nps .dl:active {
  cursor: grabbing;
}

.uvq15-nps .dl:focus-visible {
  box-shadow: 0 0 0 3px var(--bg),0 0 0 5px var(--c1);
}

.uvq15-nps svg {
  display: block;
  width: 100%;
  height: 100%;
  overflow: visible;
}

.uvq15-nps .bz {
  fill: #a1a1aa;
  stroke: #e4e4e7;
  stroke-width: 2;
  filter: drop-shadow(0 6px 10px rgba(0,0,0,.35));
}

.uvq15-nps .fc {
  fill: var(--c2);
}

.uvq15-nps .mj {
  stroke: #f4f4f5;
  stroke-width: 2.4;
}

.uvq15-nps .mn {
  stroke: #a1a1aa;
  stroke-width: 1.2;
}

.uvq15-nps text {
  fill: #e4e4e7;
  font: 700 12px ui-monospace,"SF Mono",Menlo,monospace;
  text-anchor: middle;
  dominant-baseline: central;
}

.uvq15-nps .nd path {
  fill: var(--c1);
  filter: drop-shadow(0 0 3px var(--c1));
}

.uvq15-nps .hb {
  fill: #3f3f46;
  stroke: #71717a;
  stroke-width: 1.5;
}

.uvq15-nps .hc {
  fill: var(--c1);
}

.uvq15-nps .rd {
  position: absolute;
  left: 50%;
  top: 62%;
  display: grid;
  justify-items: center;
  translate: -50% 0;
  pointer-events: none;
}

.uvq15-nps .rd b {
  font: 800 2.1em/1 ui-monospace,"SF Mono",Menlo,monospace;
  color: var(--z);
  text-shadow: 0 0 .4em var(--z);
  transition: color calc(0.3s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq15-nps .rd span {
  margin-top: .25em;
  font-size: .62em;
  font-weight: 700;
  letter-spacing: .14em;
  text-transform: uppercase;
  color: #d4d4d8;
}

.uvq15-nps .ht {
  margin: 0;
  font-size: .72em;
  color: color-mix(in srgb,var(--fg) 55%,transparent);
}

