css:
.uvq15-ptn {
  --c1: #a3e635;
  --c2: #f43f5e;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uvq15-ptn {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  display: grid;
  justify-items: center;
  gap: .5em;
  width: 15em;
  padding: 1.3em 1.2em 1em;
  border-radius: 1.6em;
  color: #f8fafc;
  background: radial-gradient(120% 80% at 50% 0,#312e81,#0b1020 70%);
  box-shadow: 0 1.4em 2.6em -1.6em rgba(0,0,0,.6),inset 0 0 0 1px rgba(255,255,255,.08);
}

.uvq15-ptn .lk {
  display: grid;
  place-items: center;
  width: 2.4em;
  height: 2.4em;
  border-radius: 50%;
  color: #cbd5e1;
  background: rgba(255,255,255,.08);
  transition: color calc(0.3s / var(--k)) cubic-bezier(.25,.1,.25,1),background calc(0.3s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq15-ptn .lk svg {
  width: 1.3em;
  height: 1.3em;
  overflow: visible;
}

.uvq15-ptn .sh {
  transform-origin: 16px 11px;
  transition: transform calc(0.45s / var(--k)) cubic-bezier(.34,1.56,.64,1);
}

.uvq15-ptn.good .lk {
  color: #1a2e05;
  background: var(--c1);
}

.uvq15-ptn.good .sh {
  transform: translateY(-2px) rotate(30deg);
}

.uvq15-ptn .msg {
  margin: 0;
  font-weight: 700;
  min-height: 1.3em;
  transition: color calc(0.2s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq15-ptn.bad .msg {
  color: var(--c2);
}

.uvq15-ptn.good .msg {
  color: var(--c1);
}

.uvq15-ptn .pad {
  position: relative;
  width: 12em;
  aspect-ratio: 1;
  touch-action: none;
  user-select: none;
  -webkit-user-select: none;
  cursor: crosshair;
}

.uvq15-ptn .pad svg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  overflow: visible;
  pointer-events: none;
}

.uvq15-ptn .ln,.uvq15-ptn .tl {
  fill: none;
  stroke: var(--c1);
  stroke-width: 7;
  stroke-linecap: round;
  stroke-linejoin: round;
  opacity: .85;
}

.uvq15-ptn .tl {
  opacity: 0;
}

.uvq15-ptn.bad .ln {
  stroke: var(--c2);
}

.uvq15-ptn.bad .pad {
  animation: uvq15-ptn-x calc(0.45s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

@keyframes uvq15-ptn-x {
  20% {
    transform: translateX(-.4em);
  }
  40% {
    transform: translateX(.35em);
  }
  60% {
    transform: translateX(-.25em);
  }
  80% {
    transform: translateX(.12em);
  }
}

.uvq15-ptn .dt {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  position: absolute;
  width: 1.05em;
  height: 1.05em;
  margin: -.525em 0 0 -.525em;
