.uvq15-dlr {
  --c1: #4f46e5;
  --c2: #10b981;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uvq15-dlr {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  position: relative;
  border-radius: 1.3em;
  background: color-mix(in srgb,var(--fg) 3%,var(--bg));
  box-shadow: 0 0 0 1px color-mix(in srgb,var(--fg) 10%,transparent),0 1.4em 2.6em -1.8em rgba(0,0,0,.35);
  display: grid;
  justify-items: center;
  gap: 1em;
  width: 17em;
  padding: 1.1em;
}

.uvq15-dlr .fl {
  display: flex;
  align-items: center;
  gap: .7em;
  justify-self: stretch;
}

.uvq15-dlr .ic {
  display: grid;
  place-items: center;
  width: 2.6em;
  height: 3.1em;
  border-radius: .4em;
  font-size: .7em;
  font-weight: 900;
  color: #fff;
  background: linear-gradient(135deg,#f87171,#dc2626);
  clip-path: polygon(0 0,72% 0,100% 22%,100% 100%,0 100%);
}

.uvq15-dlr .fl b {
  display: block;
  font-size: .9em;
}

.uvq15-dlr .fl small {
  font-size: .75em;
  color: color-mix(in srgb,var(--fg) 55%,transparent);
}

.uvq15-dlr .bt {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  position: relative;
  display: grid;
  grid-template-columns: minmax(0,1fr);
  place-items: center;
  overflow: hidden;
  width: 13em;
  height: 3.2em;
  border-radius: 2em;
  color: #fff;
  background: var(--c1);
  box-shadow: 0 .7em 1.4em -.8em var(--c1);
  transition: width calc(0.5s / var(--k)) cubic-bezier(.22,1,.36,1),background calc(0.35s / var(--k)) cubic-bezier(.25,.1,.25,1),box-shadow calc(0.35s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq15-dlr .bt:hover {
  filter: brightness(1.08);
}

.uvq15-dlr .bt:active {
  transform: scale(.97);
}

.uvq15-dlr .bt:focus-visible {
  outline: 2px solid var(--c1);
  outline-offset: 3px;
}

.uvq15-dlr .bt>* {
  grid-area: 1/1;
}

.uvq15-dlr .lb {
  display: flex;
  align-items: center;
  gap: .45em;
  font-weight: 700;
  white-space: nowrap;
  transition: opacity calc(0.2s / var(--k)) cubic-bezier(.25,.1,.25,1),transform calc(0.4s / var(--k)) cubic-bezier(.22,1,.36,1);
}

.uvq15-dlr .lb svg {
  width: 1.2em;
  height: 1.2em;
}

.uvq15-dlr .b,.uvq15-dlr .pc,.uvq15-dlr .ok,.uvq15-dlr .rg {
  opacity: 0;
}

.uvq15-dlr .b {
  transform: translateY(.6em);
}

.uvq15-dlr .rg {
  width: 3.2em;
  height: 3.2em;
  transform: rotate(-90deg);
  transition: opacity calc(0.25s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq15-dlr .rg circle {
  fill: none;
  stroke-width: 3;
}

.uvq15-dlr .tr {
  stroke: rgba(255,255,255,.25);
}

.uvq15-dlr .pg {
  stroke: #fff;
  stroke-linecap: round;
  stroke-dasharray: 100;
  stroke-dashoffset: 100;
}

.uvq15-dlr .pc {
