}

.uvq15-dlr.ok .bt,.uvq15-dlr.op .bt {
  background: var(--c2);
  box-shadow: 0 .7em 1.4em -.8em var(--c2);
}

.uvq15-dlr.ok .ok {
  opacity: 1;
}

.uvq15-dlr.ok .ok path {
