.uvq15-vot {
  --c1: #f97316;
  --c2: #6366f1;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uvq15-vot {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  position: relative;
  border-radius: 1.3em;
  background: color-mix(in srgb,var(--fg) 3%,var(--bg));
  box-shadow: 0 0 0 1px color-mix(in srgb,var(--fg) 10%,transparent),0 1.4em 2.6em -1.8em rgba(0,0,0,.35);
  display: flex;
  gap: .9em;
  width: 20em;
  padding: 1em;
}

.uvq15-vot .vb {
  flex: none;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: .1em;
  padding: .3em;
  border-radius: 2em;
  background: color-mix(in srgb,var(--fg) 6%,transparent);
}

.uvq15-vot .vb button {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  display: grid;
  place-items: center;
  width: 2.2em;
  height: 2.2em;
  border-radius: 50%;
  color: color-mix(in srgb,var(--fg) 55%,transparent);
  transition: color calc(0.2s / var(--k)) cubic-bezier(.25,.1,.25,1),background calc(0.2s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq15-vot .vb button:hover {
  background: color-mix(in srgb,var(--fg) 6%,transparent);
  color: var(--fg);
}

.uvq15-vot .vb button:focus-visible {
  outline: 2px solid var(--c1);
  outline-offset: 3px;
}

.uvq15-vot .vb svg {
  width: 1.25em;
  height: 1.25em;
  fill: transparent;
  transition: fill calc(0.2s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq15-vot .vb .up[aria-pressed="true"] {
  color: var(--c1);
}

.uvq15-vot .vb .dn[aria-pressed="true"] {
  color: var(--c2);
}

.uvq15-vot button[aria-pressed="true"] svg {
  fill: currentColor;
}

.uvq15-vot .up.go svg {
  animation: uvq15-vot-u calc(0.45s / var(--k)) cubic-bezier(.34,1.56,.64,1);
}

.uvq15-vot .dn.go svg {
  animation: uvq15-vot-d calc(0.45s / var(--k)) cubic-bezier(.34,1.56,.64,1);
}

@keyframes uvq15-vot-u {
  40% {
    transform: translateY(-.35em) scale(1.15);
  }
}

@keyframes uvq15-vot-d {
  40% {
    transform: translateY(.35em) scale(1.15);
  }
}

.uvq15-vot .n {
  display: flex;
  font-size: .85em;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
  line-height: 1.3;
  transition: color calc(0.2s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq15-vot.vu .n {
  color: var(--c1);
}

.uvq15-vot.vd .n {
  color: var(--c2);
}

.uvq15-vot .n .c {
  position: relative;
  display: block;
  height: 1.3em;
  overflow: hidden;
}

.uvq15-vot .n i {
  display: block;
  font-style: normal;
}

.uvq15-vot .n .o {
  position: absolute;
  left: 0;
  top: 0;
}

.uvq15-vot .n.u .nw {
  animation: uvq15-vot-iu calc(0.4s / var(--k)) cubic-bezier(.22,1,.36,1) both;
}

.uvq15-vot .n.u .o {
  animation: uvq15-vot-ou calc(0.4s / var(--k)) cubic-bezier(.22,1,.36,1) both;
}

.uvq15-vot .n.d .nw {
  animation: uvq15-vot-id calc(0.4s / var(--k)) cubic-bezier(.22,1,.36,1) both;
}

.uvq15-vot .n.d .o {
  animation: uvq15-vot-od calc(0.4s / var(--k)) cubic-bezier(.22,1,.36,1) both;
}

@keyframes uvq15-vot-iu {
  from {
    transform: translateY(100%);
  }
}

@keyframes uvq15-vot-ou {
  to {
    transform: translateY(-100%);
  }
}

@keyframes uvq15-vot-id {
  from {
    transform: translateY(-100%);
  }
}

@keyframes uvq15-vot-od {
  to {
    transform: translateY(100%);
  }
}

.uvq15-vot .ps {
  display: grid;
  align-content: center;
  gap: .4em;
  min-width: 0;
}

.uvq15-vot .mt,.uvq15-vot .tg {
  display: flex;
  flex-wrap: wrap;
  gap: .3em .7em;
  margin: 0;
  font-size: .72em;
  color: color-mix(in srgb,var(--fg) 55%,transparent);
}

.uvq15-vot .ps b {
  font-size: 1em;
  line-height: 1.3;
}

.uvq15-vot .tg span:first-child {
  padding: .15em .6em;
  border-radius: 1em;
  font-weight: 700;
  color: var(--c1);
  background: color-mix(in srgb,var(--c1) 14%,transparent);
}

.uvq15-vot .sr {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}

@media (prefers-reduced-motion:reduce) {
  .uvq15-vot,.uvq15-vot *,.uvq15-vot *::before,.uvq15-vot *::after {
    animation-duration: .01ms!important;
    animation-iteration-count: 1!important;
    transition-duration: .01ms!important;
  }
}

