  display: flex;
  align-items: center;
  gap: .55em;
  padding: .7em .8em;
}

.uvq15-dbl .av {
  display: grid;
  place-items: center;
  width: 2em;
  height: 2em;
  border-radius: 50%;
  font-size: .85em;
  font-weight: 800;
  color: #fff;
  background: linear-gradient(135deg,var(--c2),var(--c1));
