css:
.uvq15-pin {
  --c1: #dc2626;
  --c2: #fef08a;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uvq15-pin {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  display: grid;
  justify-items: center;
  gap: .7em;
  width: 21em;
}

.uvq15-pin .bd {
  display: grid;
  grid-template-columns: repeat(3,1fr);
  gap: .8em;
  width: 100%;
  box-sizing: border-box;
  padding: 1.5em 1em 1.3em;
  border-radius: .5em;
  background: radial-gradient(circle at 20% 30%,rgba(120,70,30,.35) 0 1px,transparent 1.5px) 0 0/7px 7px,radial-gradient(circle at 60% 70%,rgba(255,230,190,.3) 0 1px,transparent 1.5px) 0 0/9px 9px,radial-gradient(circle at 40% 50%,rgba(90,50,20,.25) 0 1.5px,transparent 2px) 0 0/13px 11px,#b98352;
  box-shadow: inset 0 0 0 .55em #7c4a24,inset 0 0 0 .65em #5b3418,inset 0 .4em 1em .55em rgba(0,0,0,.25),0 1em 1.8em -1em rgba(0,0,0,.5);
}

.uvq15-pin .nt {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  position: relative;
  display: grid;
  align-content: center;
  aspect-ratio: 1;
  padding: .6em;
  color: #292524;
  background: linear-gradient(170deg,rgba(255,255,255,.35),transparent 40%),var(--c);
  transform: rotate(var(--r)) translateY(-.2em);
  box-shadow: .3em .8em 1em -.3em rgba(0,0,0,.45);
  transform-origin: 50% .5em;
  transition: transform calc(0.45s / var(--k)) cubic-bezier(.22,1,.36,1),box-shadow calc(0.45s / var(--k)) cubic-bezier(.22,1,.36,1);
}

.uvq15-pin .nt:hover {
  transform: rotate(calc(var(--r) * 1.4)) translateY(-.4em);
  box-shadow: .4em 1.1em 1.2em -.3em rgba(0,0,0,.45);
}

.uvq15-pin .nt:focus-visible {
  outline: 2px solid #fff;
  outline-offset: 3px;
}

.uvq15-pin .tx {
  font: 600 .8em/1.25 "Segoe Print","Bradley Hand","Chalkboard SE","Comic Sans MS",cursive;
  text-align: center;
}

.uvq15-pin .nt[aria-pressed="true"] {
  transform: rotate(calc(var(--r) * .25));
  box-shadow: .1em .25em .35em -.1em rgba(0,0,0,.4);
}

.uvq15-pin .pn {
  position: absolute;
  left: 50%;
  top: .15em;
  width: 1em;
  height: 1em;
  margin-left: -.5em;
  border-radius: 50%;
  background: radial-gradient(circle at 35% 30%,color-mix(in srgb,var(--c1) 40%,#fff),var(--c1) 55%,color-mix(in srgb,var(--c1) 55%,#000));
  box-shadow: .15em .3em .3em rgba(0,0,0,.45);
  opacity: 0;
  transform: translateY(-2.2em) scale(1.6);
}

.uvq15-pin .nt[aria-pressed="true"] .pn {
  opacity: 1;
  transform: none;
}

.uvq15-pin .nt.in .pn {
  animation: uvq15-pin-in calc(0.45s / var(--k)) cubic-bezier(.5,0,.75,0) both;
}

.uvq15-pin .nt.in {
  animation: uvq15-pin-hit calc(0.6s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq15-pin .nt.out .pn {
  animation: uvq15-pin-out calc(0.45s / var(--k)) cubic-bezier(.25,.1,.25,1) both;
}

.uvq15-pin .nt.out {
  animation: uvq15-pin-sw calc(0.9s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

@keyframes uvq15-pin-in {
  0% {
    opacity: 0;
    transform: translateY(-2.2em) scale(1.6);
  }
  30% {
    opacity: 1;
  }
  80% {
    transform: translateY(.1em) scale(.95);
  }
  100% {
    opacity: 1;
    transform: none;
  }
}

@keyframes uvq15-pin-hit {
  0%,55% {
    transform: rotate(var(--r)) translateY(-.2em);
  }
  70% {
    transform: rotate(calc(var(--r) * .2)) translateY(.1em) scale(.98);
  }
  100% {
    transform: rotate(calc(var(--r) * .25));
  }
}

@keyframes uvq15-pin-out {
  0% {
    opacity: 1;
    transform: none;
  }
  100% {
    opacity: 0;
    transform: translate(.6em,-2em) rotate(40deg);
  }
}

@keyframes uvq15-pin-sw {
  0% {
    transform: rotate(calc(var(--r) * .25));
  }
  30% {
    transform: rotate(calc(var(--r) * -1.6)) translateY(-.2em);
  }
  55% {
    transform: rotate(calc(var(--r) * 1.6)) translateY(-.2em);
  }
  78% {
    transform: rotate(calc(var(--r) * .7)) translateY(-.2em);
  }
  100% {
    transform: rotate(var(--r)) translateY(-.2em);
  }
}

.uvq15-pin .hd {
  margin: 0;
  font-size: .75em;
  color: color-mix(in srgb,var(--fg) 55%,transparent);
}

@media (prefers-reduced-motion:reduce) {
  .uvq15-pin,.uvq15-pin *,.uvq15-pin *::before,.uvq15-pin *::after {
    animation-duration: .01ms!important;
    animation-iteration-count: 1!important;
    transition-duration: .01ms!important;
  }
}

