}

.uvq15-trs .go:hover {
  filter: brightness(1.08);
}

.uvq15-trs .go:active,.uvq15-trs .un:active {
  transform: scale(.96);
}

.uvq15-trs .go:focus-visible,.uvq15-trs .un:focus-visible {
