  outline-offset: 3px;
}

.uvq15-trs .go svg,.uvq15-trs .un svg {
  width: 1.15em;
  height: 1.15em;
}

.uvq15-trs [hidden] {
  display: none;
}

.uvq15-trs .sr {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}

