css:
.uvq15-thm {
  --c1: #16a34a;
  --c2: #e11d48;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uvq15-thm {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  position: relative;
  border-radius: 1.3em;
  background: color-mix(in srgb,var(--fg) 3%,var(--bg));
  box-shadow: 0 0 0 1px color-mix(in srgb,var(--fg) 10%,transparent),0 1.4em 2.6em -1.8em rgba(0,0,0,.35);
  display: grid;
  justify-items: center;
  width: 18em;
  padding: 1.1em 1.1em .9em;
  text-align: center;
}

.uvq15-thm .q {
  margin: 0 0 .8em;
  font-weight: 700;
}

.uvq15-thm .ch {
  display: flex;
  justify-content: center;
  gap: .6em;
}

.uvq15-thm .ch button {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  position: relative;
  display: flex;
  align-items: center;
  gap: .45em;
  max-width: 8em;
  padding: .6em 1.1em;
  border-radius: 2em;
  font-weight: 700;
  white-space: nowrap;
  background: color-mix(in srgb,var(--fg) 6%,transparent);
  box-shadow: inset 0 0 0 1px color-mix(in srgb,var(--fg) 10%,transparent);
  transition: max-width calc(0.45s / var(--k)) cubic-bezier(.22,1,.36,1),padding calc(0.45s / var(--k)) cubic-bezier(.22,1,.36,1),opacity calc(0.25s / var(--k)) cubic-bezier(.25,.1,.25,1),background calc(0.25s / var(--k)) cubic-bezier(.25,.1,.25,1),color calc(0.25s / var(--k)) cubic-bezier(.25,.1,.25,1),transform .15s cubic-bezier(.25,.1,.25,1);
}

.uvq15-thm .ch button:hover {
  background: color-mix(in srgb,var(--fg) 10%,transparent);
}

.uvq15-thm .ch button:active {
  transform: scale(.95);
}

.uvq15-thm .ch button:focus-visible {
  outline: 2px solid var(--c1);
  outline-offset: 3px;
}

.uvq15-thm .ch svg {
  flex: none;
  width: 1.3em;
  height: 1.3em;
}

.uvq15-thm .y[aria-pressed="true"] {
  color: #fff;
  background: var(--c1);
  box-shadow: none;
}

.uvq15-thm .n[aria-pressed="true"] {
  color: #fff;
  background: var(--c2);
  box-shadow: none;
}

.uvq15-thm.yes .n,.uvq15-thm.no .y {
  max-width: 0;
  padding-left: 0;
  padding-right: 0;
  opacity: 0;
  overflow: hidden;
  pointer-events: none;
}

.uvq15-thm.yes .ch,.uvq15-thm.no .ch {
  gap: 0;
}

.uvq15-thm.yes .y svg {
  animation: uvq15-thm-u calc(0.6s / var(--k)) cubic-bezier(.34,1.56,.64,1);
}

.uvq15-thm.no .n svg {
  animation: uvq15-thm-d calc(0.6s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

@keyframes uvq15-thm-u {
  40% {
    transform: translateY(-.3em) rotate(-22deg) scale(1.25);
  }
}

@keyframes uvq15-thm-d {
  25% {
    transform: rotate(14deg) translateY(.15em);
  }
  50% {
    transform: rotate(-8deg);
  }
  75% {
    transform: rotate(6deg);
  }
}

.uvq15-thm .cf {
  position: absolute;
  left: 1.75em;
  top: 50%;
  pointer-events: none;
}

.uvq15-thm .cf i {
  position: absolute;
  width: .35em;
  height: .35em;
  margin: -.175em;
  border-radius: .1em;
  background: var(--c1);
  opacity: 0;
}

.uvq15-thm .cf i:nth-child(3n+1) {
  background: #facc15;
}

.uvq15-thm .cf i:nth-child(3n+2) {
  background: #38bdf8;
}

.uvq15-thm.yes .cf i {
  animation: uvq15-thm-c calc(0.8s / var(--k)) cubic-bezier(.22,1,.36,1);
}

@keyframes uvq15-thm-c {
  0% {
    opacity: 1;
    transform: rotate(var(--a)) translateY(-.4em);
  }
  100% {
    opacity: 0;
    transform: rotate(var(--a)) translateY(-2.6em) rotate(160deg);
  }
}

.uvq15-thm .mo {
  display: grid;
  grid-template-rows: 0fr;
  width: 100%;
  transition: grid-template-rows calc(0.45s / var(--k)) cubic-bezier(.22,1,.36,1);
}

.uvq15-thm.no:not(.sent) .mo {
  grid-template-rows: 1fr;
}

.uvq15-thm .fm {
  display: grid;
  gap: .5em;
  min-height: 0;
  overflow: hidden;
}

.uvq15-thm textarea {
  margin-top: .8em;
  padding: .6em .8em;
  border: 0;
  border-radius: .7em;
  resize: none;
  font: inherit;
  font-size: .85em;
  color: inherit;
  background: color-mix(in srgb,var(--fg) 6%,transparent);
  box-shadow: inset 0 0 0 1px color-mix(in srgb,var(--fg) 10%,transparent);
  outline: 0;
}

.uvq15-thm textarea:focus-visible {
  box-shadow: inset 0 0 0 2px var(--c2);
}

.uvq15-thm .sd {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  justify-self: end;
  margin: 0 .1em .2em;
  padding: .5em 1em;
  border-radius: .6em;
  font-size: .85em;
  font-weight: 700;
  color: #fff;
  background: var(--c2);
}

.uvq15-thm .sd:focus-visible {
  outline: 2px solid var(--c1);
  outline-offset: 3px;
}

.uvq15-thm .ty {
  min-height: 1.3em;
  margin: .6em 0 0;
  font-size: .85em;
  font-weight: 600;
  color: color-mix(in srgb,var(--fg) 55%,transparent);
}

.uvq15-thm .ty:not(:empty) {
  animation: uvq15-thm-t calc(0.4s / var(--k)) cubic-bezier(.22,1,.36,1);
}

@keyframes uvq15-thm-t {
  from {
    opacity: 0;
    transform: translateY(.4em);
  }
}

.uvq15-thm .rs {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  margin-top: .2em;
  font-size: .72em;
  text-decoration: underline;
  color: color-mix(in srgb,var(--fg) 55%,transparent);
}

.uvq15-thm .rs[hidden] {
  display: none;
}

.uvq15-thm .rs:focus-visible {
  outline: 2px solid var(--c1);
  outline-offset: 3px;
}

@media (prefers-reduced-motion:reduce) {
  .uvq15-thm,.uvq15-thm *,.uvq15-thm *::before,.uvq15-thm *::after {
    animation-duration: .01ms!important;
    animation-iteration-count: 1!important;
    transition-duration: .01ms!important;
  }
}

