  width: 19em;
  padding: .8em;
  --dx: 0px;
}

.uvq15-voc .ls {
  display: flex;
  flex-direction: column;
  gap: .4em;
  height: 9.5em;
  margin: 0 0 .7em;
  padding: 0;
  overflow: hidden;
  list-style: none;
  justify-content: flex-end;
}

.uvq15-voc li {
  max-width: 82%;
}

.uvq15-voc .in span {
  display: block;
  padding: .5em .8em;
  border-radius: 1.1em 1.1em 1.1em .3em;
  font-size: .85em;
  background: color-mix(in srgb,var(--fg) 6%,transparent);
}

.uvq15-voc .out {
  align-self: flex-end;
  display: flex;
  align-items: center;
  gap: .5em;
  padding: .4em .7em .4em .4em;
  border-radius: 1.1em 1.1em .3em 1.1em;
  color: #fff;
  background: var(--c1);
  animation: uvq15-voc-n calc(0.45s / var(--k)) cubic-bezier(.22,1,.36,1);
}

@keyframes uvq15-voc-n {
  from {
    opacity: 0;
    transform: translateY(.6em) scale(.9);
  }
}

.uvq15-voc .pb {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  display: grid;
  place-items: center;
  width: 2em;
  height: 2em;
  border-radius: 50%;
  color: var(--c1);
  background: #fff;
}

.uvq15-voc .pb:focus-visible {
  outline: 2px solid #fff;
  outline-offset: 2px;
}

.uvq15-voc .pb svg {
  width: 1em;
  height: 1em;
  fill: currentColor;
}

.uvq15-voc .pb .p2,.uvq15-voc .pl .pb .p1 {
  display: none;
}

.uvq15-voc .pl .pb .p2 {
  display: inline;
}

.uvq15-voc .wb {
  position: relative;
  display: flex;
  align-items: center;
  gap: 2px;
  height: 1.6em;
}

.uvq15-voc .wb i {
  width: 2px;
  height: calc(var(--h) * 100%);
  border-radius: 2px;
  background: rgba(255,255,255,.45);
}

.uvq15-voc .wb .f {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  gap: 2px;
  clip-path: inset(0 100% 0 0);
}

.uvq15-voc .wb .f i {
  background: #fff;
}

.uvq15-voc .pl .wb .f {
  animation: uvq15-voc-pg var(--d) linear forwards;
}

@keyframes uvq15-voc-pg {
  to {
    clip-path: inset(0 0 0 0);
  }
}

.uvq15-voc .out time {
  font-size: .7em;
  font-variant-numeric: tabular-nums;
  opacity: .85;
}

.uvq15-voc .bar {
  display: flex;
  align-items: center;
  gap: .5em;
}

.uvq15-voc .ip {
  position: relative;
  flex: 1;
  display: grid;
  align-items: center;
  height: 2.6em;
  padding: 0 .9em;
  border-radius: 2em;
  background: color-mix(in srgb,var(--fg) 6%,transparent);
  overflow: hidden;
}

.uvq15-voc .ip>* {
  grid-area: 1/1;
}

.uvq15-voc .ph {
  font-size: .8em;
  color: color-mix(in srgb,var(--fg) 55%,transparent);
  white-space: nowrap;
