}

@keyframes uvq15-voc-b {
  50% {
    opacity: .25;
  }
}

.uvq15-voc .tm {
  font-size: .8em;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}

.uvq15-voc .wv {
  display: flex;
  align-items: center;
  gap: 2px;
  height: 1.4em;
}

.uvq15-voc .wv i {
  width: 2px;
  height: calc(var(--h,.15) * 100%);
  border-radius: 2px;
  background: var(--fg);
  opacity: .6;
  transition: height .09s linear;
}

.uvq15-voc .cx {
  display: flex;
  align-items: center;
  gap: .1em;
  margin-left: auto;
  font-size: .68em;
  color: color-mix(in srgb,var(--fg) 55%,transparent);
  white-space: nowrap;
  transform: translateX(calc(var(--dx) * .4));
  opacity: calc(1 + var(--dx) / 90px);
}

.uvq15-voc .cx svg {
  width: 1.1em;
  height: 1.1em;
}

.uvq15-voc.on .ph {
  opacity: 0;
}

.uvq15-voc.on .rec {
  opacity: 1;
  transform: none;
}

.uvq15-voc.cx .dot {
  background: color-mix(in srgb,var(--fg) 55%,transparent);
}

.uvq15-voc .mc {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  position: relative;
  flex: none;
  display: grid;
  place-items: center;
  width: 2.6em;
  height: 2.6em;
  border-radius: 50%;
  color: #fff;
  background: var(--c1);
  touch-action: none;
  user-select: none;
  -webkit-user-select: none;
  -webkit-touch-callout: none;
  transition: transform calc(0.3s / var(--k)) cubic-bezier(.34,1.56,.64,1),background calc(0.2s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq15-voc .mc svg {
  width: 1.25em;
  height: 1.25em;
}

.uvq15-voc .mc:focus-visible {
  outline: 2px solid var(--c1);
  outline-offset: 3px;
}

.uvq15-voc .mc::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: 50%;
  background: var(--c2);
  opacity: 0;
  transform: scale(1);
}

.uvq15-voc.on .mc {
  background: var(--c2);
  transform: translateX(var(--dx)) scale(1.35);
}

.uvq15-voc.on .mc::before {
  animation: uvq15-voc-r calc(1.2s / var(--k)) ease-out infinite;
}

@keyframes uvq15-voc-r {
  0% {
    opacity: .45;
    transform: scale(1);
  }
  100% {
    opacity: 0;
    transform: scale(1.9);
  }
}

.uvq15-voc .mc.hint {
  animation: uvq15-voc-h calc(0.4s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

@keyframes uvq15-voc-h {
  25% {
    transform: translateX(-.25em);
  }
  75% {
    transform: translateX(.25em);
  }
}

.uvq15-voc.del .ip {
  animation: uvq15-voc-x calc(0.5s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

@keyframes uvq15-voc-x {
  20% {
    background: color-mix(in srgb,var(--c2) 22%,transparent);
    transform: translateX(-.3em);
  }
  50% {
    transform: translateX(.25em);
  }
}

.uvq15-voc .sr {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}

@media (prefers-reduced-motion:reduce) {
  .uvq15-voc,.uvq15-voc *,.uvq15-voc *::before,.uvq15-voc *::after {
    animation-duration: .01ms!important;
    animation-iteration-count: 1!important;
    transition-duration: .01ms!important;
  }
}

