css:
.uvq15-tap {
  --c1: #facc15;
  --c2: #dc2626;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fr: 70;
  /* inercia */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uvq15-tap {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  display: grid;
  gap: .7em;
  width: 19em;
  --u: calc(var(--s,16px) * .55);
}

.uvq15-tap .hd {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  margin: 0;
  font-weight: 700;
}

.uvq15-tap .v b {
  font-size: 2.4em;
  font-weight: 900;
  letter-spacing: -.04em;
  font-variant-numeric: tabular-nums;
}

.uvq15-tap .v small {
  margin-left: .2em;
  font-size: .85em;
  color: color-mix(in srgb,var(--fg) 55%,transparent);
}

.uvq15-tap .win {
  position: relative;
  height: 4.4em;
  border-radius: .7em;
  overflow: hidden;
  background: #27272a;
  box-shadow: inset 0 .3em .6em rgba(0,0,0,.5),0 0 0 1px color-mix(in srgb,var(--fg) 10%,transparent);
  cursor: grab;
  touch-action: none;
  user-select: none;
  outline: 0;
  -webkit-mask-image: linear-gradient(90deg,transparent,#000 18%,#000 82%,transparent);
  mask-image: linear-gradient(90deg,transparent,#000 18%,#000 82%,transparent);
}

.uvq15-tap.drag .win {
  cursor: grabbing;
}

.uvq15-tap .win:focus-visible {
  box-shadow: inset 0 0 0 3px var(--c2);
}

.uvq15-tap:has(.win:focus-visible) .hd b {
  color: var(--c2);
}

.uvq15-tap .tp {
  position: absolute;
  left: calc(50% - 50 * var(--u));
  top: .5em;
  bottom: .5em;
  width: calc(100 * var(--u) + 1px);
  border-radius: .2em;
  background: linear-gradient(90deg,#1c1917 1px,transparent 0) 0 0/var(--u) 26% repeat-x,linear-gradient(90deg,#1c1917 1px,transparent 0) 0 0/calc(5 * var(--u)) 42% repeat-x,linear-gradient(90deg,#1c1917 1.5px,transparent 0) 0 0/calc(10 * var(--u)) 60% repeat-x,linear-gradient(transparent 70%,rgba(0,0,0,.12)),var(--c1);
  box-shadow: 0 0 0 1em var(--c1),inset 0 1px 0 rgba(255,255,255,.4);
  will-change: transform;
}

.uvq15-tap .tp span {
  position: absolute;
  bottom: .15em;
  translate: -50% 0;
  font: 800 .7em ui-monospace,"SF Mono",Menlo,monospace;
  color: #1c1917;
}

.uvq15-tap .mk {
  position: absolute;
  left: 50%;
  top: 0;
  bottom: 0;
  width: 2px;
  margin-left: -1px;
  background: var(--c2);
  box-shadow: 0 0 .5em var(--c2);
}

.uvq15-tap .mk::before {
  content: "";
  position: absolute;
  left: 50%;
  top: 0;
  border: .4em solid transparent;
  border-top-color: var(--c2);
  translate: -50% 0;
}

.uvq15-tap .ht {
  margin: 0;
  font-size: .72em;
  text-align: center;
  color: color-mix(in srgb,var(--fg) 55%,transparent);
}

